/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeInventTableCostModel extends UPSPricingAttributeInventTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(InventTable, CostModel);
}

public Set getAllowedValues()
{
    SysDictEnum     sysDictEnum = new SysDictEnum(enumNum(ItemCostModel));
    var             ret = new Set(Types::String);
    ItemCostModel   enum;

    for (int i = 0; i < sysDictEnum.values(); ++i)
    {
        enum = sysDictEnum.index2Value(i);
        ret.add(enum2Str(enum));
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(InventTable, CostModel));
    qbr.value(queryValue(_value));
}
